param([string]$Tag)
$ErrorActionPreference = "Stop"
$out = "C:\Users\Joe\.codex\ob64-legion-0006d7d8-build\scratch"
$cc1 = "C:\Users\Joe\.codex\ob64-phase6-kmc-20260801\clean-d\toolchain\kmc-gcc-2.7.2\cc1.exe"
$as  = ".toolchains\gnu-binutils-2.6-mips-kmc-elf-msys2\bin\mips-kmc-elf-as.exe"
$od  = ".toolchains\gnu-binutils-2.6-mips-kmc-elf-msys2\bin\mips-kmc-elf-objdump.exe"
$oc  = ".toolchains\gnu-binutils-2.6-mips-kmc-elf-msys2\bin\mips-kmc-elf-objcopy.exe"

& $cc1 -quiet -O2 -meb -mips3 -mgp32 -mfp32 -G 0 -fno-PIC -mno-abicalls -fno-builtin -funsigned-char -o "$out\$tag.s" "$out\$tag.c" 1>$null 2>$null
if ($LASTEXITCODE -ne 0) { echo "COMPILE FAIL"; exit 1 }
& $as -G 0 -mips3 -mabi=32 -force-n64align -EB -o "$out\$tag.o" "$out\$tag.s" 1>$null 2>$null
if ($LASTEXITCODE -ne 0) { echo "ASSEMBLE FAIL"; exit 1 }
& $od -d "$out\$tag.o" > "$out\$tag.dis"

node -e "
const fs=require('fs');
const rom=fs.readFileSync('build/baserom.us_rev0.z64');
const expected=rom.subarray(0x6D7D8,0x6D96C);
const {execSync}=require('child_process');
const bin='$out\\$tag'.replace(/\\\\/g,'\\\\');
" 2>$null

# Extract .text via objcopy binary dump
& $oc -O binary --only-section=.text "$out\$tag.o" "$out\$tag.bin"
$cur = [System.IO.File]::ReadAllBytes("$out\$tag.bin")
$romBytes = [System.IO.File]::ReadAllBytes((Join-Path (Get-Location) 'build\baserom.us_rev0.z64'))
$exp = $romBytes[0x6D7D8..0x6D95B]
"size: $($cur.Length) bytes ($($cur.Length/4) words)  target: 404 (101)"
$max=[Math]::Min($cur.Length,$exp.Length)
$diffs=@()
for($i=0;$i -lt $max;$i+=4){
  $a=([BitConverter]::ToUInt32($cur,$i)) ; $b=(( [BitConverter]::ToUInt32($exp,$i)))
  if($a -ne $b){ $diffs += ("{0:x3}: cur {1:x8} exp {2:x8}" -f $i, $a, $b) }
}
"differing words: $($diffs.Count)"
$diffs | Select-Object -First 40

const fs = require('fs');
const path = require('path');
const { parseElfFile, elfSectionBytes } = require('./tools/lib/phase7_conventional');

const tag = process.argv[2];
if (!tag) { console.error('need tag'); process.exit(1); }
const scratch = 'C:/Users/Joe/.codex/ob64-legion-0006d7d8-build/scratch';
const elf = parseElfFile(path.join(scratch, tag + '.o'));
const sections = elf.sections.filter((s) => s.name === '.text');
if (sections.length !== 1) { console.error('no .text'); process.exit(1); }
const cur = Buffer.from(elfSectionBytes(elf, sections[0]));
const rom = fs.readFileSync('build/baserom.us_rev0.z64');
const exp = rom.subarray(0x6D7D8, 0x6D96C);
console.log(`size: ${cur.length} bytes (${cur.length / 4} words)   target: 404 bytes (101 words)`);
const n = Math.min(cur.length, exp.length);
let diffs = [];
for (let i = 0; i < n; i += 4) {
  const a = cur.readUInt32BE(i);
  const b = exp.readUInt32BE(i);
  if (a !== b) {
    const cls = ((a >>> 26) === 2 || (a >>> 26) === 3) && ((b >>> 26) === 2 || (b >>> 26) === 3)
      ? 'J/JAL' : '';
    diffs.push(`0x${i.toString(16).padStart(3, '0')}: cur ${a.toString(16).padStart(8, '0')}  exp ${b.toString(16).padStart(8, '0')} ${cls}`);
  }
}
console.log(`differing words: ${diffs.length}${cur.length !== 404 ? '  (sizes differ)' : ''}`);
console.log(diffs.slice(0, 60).join('\n'));

