param([string]$BaseTag = "v8", [string]$OutTag = "padTest")
$ErrorActionPreference = "Stop"
$out = "C:\Users\Joe\.codex\ob64-legion-0006d7d8-build\scratch"
$cc1 = "C:\Users\Joe\.codex\ob64-phase6-kmc-20260801\clean-d\toolchain\kmc-gcc-2.7.2\cc1.exe"
$as  = ".toolchains\gnu-binutils-2.6-mips-kmc-elf-msys2\bin\mips-kmc-elf-as.exe"

$base = Get-Content "$out\$baseTag.c" -Raw

$declLines = @{
  bytes  = "    u8 movement_bytes[5];"
  start  = "    u8 *movement_start;"
}

$sizes = @(1,2,3,4,5,6,7,8)
$positions = @("beforeBytes","afterBytes","afterStart","afterCell","last")

foreach ($size in $sizes) {
  foreach ($pos in $positions) {
    $padDecl = "    volatile u8 reserved_frame_pad[$size];`r`n"
    $text = $base
    switch ($pos) {
      "beforeBytes" { $text = $text.Replace($declLines.bytes, $padDecl + $declLines.bytes) }
      "afterBytes"  { $text = $text.Replace($declLines.bytes, $declLines.bytes + "`r`n" + $padDecl.TrimEnd()) }
      "afterStart"  { $text = $text.Replace($declLines.start, $declLines.start + "`r`n" + $padDecl.TrimEnd()) }
      "afterCell"   { $text = $text.Replace("    u8 *cell_cursor;", "    u8 *cell_cursor;`r`n" + $padDecl.TrimEnd()) }
      "last"        { $text = $text.Replace("    u32 record_offset;", "    u32 record_offset;`r`n" + $padDecl.TrimEnd()) }
    }
    $tag = "${outTag}_${size}_$pos"
    Set-Content -Path "$out\$tag.c" -Value $text -NoNewline
    & $cc1 -quiet -O2 -meb -mips3 -mgp32 -mfp32 -G 0 -fno-PIC -mno-abicalls -fno-builtin -funsigned-char -o "$out\$tag.s" "$out\$tag.c" 1>$null 2>$null
    if ($LASTEXITCODE -ne 0) { continue }
    & $as -G 0 -mips3 -mabi=32 -force-n64align -EB -o "$out\$tag.o" "$out\$tag.s" 1>$null 2>$null
    if ($LASTEXITCODE -ne 0) { continue }
    $result = node "$out\compare.js" $tag
    $sizeLine = ($result | Select-Object -First 1)
    $diffLine = ($result | Select-Object -Skip 1)
    $lwline = (Select-String -Path "$out\$tag.dis" -Pattern "lw \\\$s1," | Select-Object -First 1).Line
    "$tag :: $sizeLine :: $diffLine :: $lwline"
  }
}

